import React, { useEffect, useState } from "react";
import "./BuyHouseList.css";
import BuySearchBar from "./BuySearchBar";

function formatCurrencyINR(n) {
  if (n == null || isNaN(n)) return "—";
  const v = Number(n);
  if (v >= 1e7) return `₹${(v / 1e7).toFixed(2)} Cr`;
  if (v >= 1e5) return `₹${(v / 1e5).toFixed(2)} L`;
  return `₹${v.toLocaleString("en-IN")}`;
}

export default function BuyHouseList() {
  const [houses, setHouses] = useState([]);
  const [allHouses, setAllHouses] = useState([]); // keep original to restore if needed
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [revealed, setRevealed] = useState({});
  const [predicted, setPredicted] = useState({});
  const [predicting, setPredicting] = useState({});

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setErr("");
      try {
        const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/buy/houses`);
        if (!res.ok) throw new Error("Failed to load");
        const data = await res.json();
        setHouses(data);
        setAllHouses(data);
      } catch (e) {
        setErr("Unable to fetch listings. Please try again.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const doPredict = async (h) => {
    const payload = {
      Area_sqft: h.area_sqft || 0,
      Property_Type: h.property_type || "",
      Bedrooms: h.bedrooms || 0,
      Bathrooms: h.bathrooms || 0,
      Year_Built: h.year_built || 0,
      Condition: h.condition || "",
      hospitalApplicable: "notApplicable",
      hospitalDistance: 0,
      schoolApplicable: "notApplicable",
      schoolDistance: 0,
      railwayApplicable: "notApplicable",
      railwayDistance: 0,
      busApplicable: "notApplicable",
      busDistance: 0,
      latitude: h.latitude || 0,
      longitude: h.longitude || 0,
    };

    setPredicting((p) => ({ ...p, [h.id]: true }));
    try {
      const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/predict/house`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error("Predict failed");
      const data = await res.json();
      setPredicted((p) => ({ ...p, [h.id]: Number(data.price) }));
    } catch (e) {
      setPredicted((p) => ({ ...p, [h.id]: null }));
      alert("Prediction failed. Please try again.");
    } finally {
      setPredicting((p) => ({ ...p, [h.id]: false }));
    }
  };

  // Handler passed to the search bar; replaces visible list with filtered results
  const handleSearchResults = (rows) => {
    setHouses(rows);
  };

  // Optional helper: restore the full list (you can add a Clear button in the search bar to call this)
  const restoreAll = () => {
    setHouses(allHouses);
  };

  if (loading) return <div className="buy-loading">Loading listings...</div>;
  if (err) return <div className="buy-error">{err}</div>;
  if (!houses.length)
    return (
      <div className="buy-root">
        <BuySearchBar onResults={handleSearchResults} />
        <div className="buy-empty">No houses found.</div>
      </div>
    );

  return (
    <div className="buy-root">
      {/* Search header */}
      <BuySearchBar onResults={handleSearchResults} />

      {/* Cards */}
      {houses.map((h) => {
        const isRevealed = revealed[h.id];
        const pred = predicted[h.id];
        const actual = h.actualPrice != null ? Number(h.actualPrice) : null;
        const showDeal =
          typeof pred === "number" && typeof actual === "number" && pred < actual;

        return (
          <div className="buy-card" key={h.id}>
            <div className="buy-card-left">
              <div className="buy-thumb">
                {h.image ? (
                  <img
                    src={`${process.env.REACT_APP_BACKEND_URL}${h.image}`}
                    alt=""
                  />
                ) : (
                  <div className="no-img">No Image</div>
                )}
                <span className="badge">Resale</span>
              </div>
            </div>

            <div className="buy-card-mid">
              <div className="buy-title">
                {h.property_type || "Property"} in {h.city || h.location || "—"}
              </div>

              <div className="buy-meta">
                <div className="price">{formatCurrencyINR(actual)}</div>
                <div className="meta-item">{h.area_sqft || "—"} sq.ft</div>
                <div className="meta-item">{h.bedrooms || "—"} Beds</div>
                <div className="meta-item">{h.bathrooms || "—"} Baths</div>
              </div>

              {pred != null && (
                <div
                  className={`predict-row ${showDeal ? "deal-ok" : "deal-warn"}`}
                >
                  <span>Model price: {formatCurrencyINR(pred)}</span>
                  {showDeal ? (
                    <span className="deal good">Good deal</span>
                  ) : (
                    <span className="deal warn">Above model</span>
                  )}
                </div>
              )}

              {(h.location || h.city) && (
                <div className="location-row">
                  <span className="pin">📍</span>
                  <span className="loc-text">{h.location || h.city}</span>
                </div>
              )}
            </div>

            <div className="buy-card-right">
              <div className="btn-row">
                <button
                  className="btn contact"
                  onClick={() =>
                    setRevealed((r) => ({ ...r, [h.id]: !isRevealed }))
                  }
                >
                  {isRevealed ? h.contact || "NA" : "Contact"}
                </button>

                <button
                  className="btn predict"
                  disabled={predicting[h.id]}
                  onClick={() => doPredict(h)}
                >
                  {predicting[h.id] ? "Predicting..." : "Predict"}
                </button>
              </div>
            </div>
          </div>
        );
      })}

      {/* Optional control to restore full list */}
      {/* <div style={{textAlign:'center', marginTop:12}}>
        <button className="btn" onClick={restoreAll}>Show All</button>
      </div> */}
    </div>
  );
}
